app = FastAPI()

oauth2_scheme_1 = OAuth2PasswordBearer(
    tokenUrl="token", 
    scopes={"me": "Read current user"}, 
    scheme_name="OAuth2"
)
oauth2_scheme_2 = OAuth2PasswordBearer(
    tokenUrl="token", 
    scopes={"me": "Read current user", "admin": "Admin access"}, 
    scheme_name="OAuth2"
)

@app.get("/me", dependencies=[Security(oauth2_scheme_1, scopes=["me"])])
def read_me():
    return {"me": "user"}

@app.get("/admin", dependencies=[Security(oauth2_scheme_2, scopes=["admin"])])
def read_admin():
    return {"admin": "admin"}

openapi_schema = get_openapi(
    title="Test",
    version="0.1.0",
    routes=app.routes,
)

import json
print(json.dumps(openapi_schema, indent=2))

